PACK:
```json
{
  "specVersion": "0.2.0-draft",
  "id": "https://example.org/judgment-packs/vendor-approval-policy",
  "version": "1.0.0",
  "title": "Vendor Approval Policy",
  "description": "Determines vendor onboarding spend requests, including evidence preconditions, sanctions handling, critical-supplier review, high-country large-exposure escalation, approvals, enhanced review, review, rejection, and unreadable-input handling.",
  "decision": {
    "intent": "Determine the disposition of a vendor onboarding spend request.",
    "question": "Should this vendor onboarding spend request be approved, reviewed, enhanced-reviewed, rejected, or left unresolved?"
  },
  "evidenceRequirements": [
    {
      "id": "financial-evidence",
      "description": "Audited financial statements must be available before any determination is issued.",
      "required": true,
      "kind": "document"
    },
    {
      "id": "insurance-certificate",
      "description": "Insurance certificate consulted only for low-country-risk requests below risk 40 with spend above 500000.00 and at most 2000000.00.",
      "required": false,
      "kind": "document"
    }
  ],
  "outcomes": [
    {
      "id": "approve",
      "label": "Approve"
    },
    {
      "id": "review",
      "label": "Review"
    },
    {
      "id": "enhanced-review",
      "label": "Enhanced review"
    },
    {
      "id": "reject",
      "label": "Reject"
    }
  ],
  "rules": [
    {
      "id": "d1-sanctions-match",
      "description": "Reject a sanctions match.",
      "when": {
        "op": "fact",
        "path": "/vendor/sanctionsStatus",
        "operator": "equals",
        "value": "MATCH"
      },
      "outcome": "reject",
      "onUnknown": "ignore",
      "evidenceRequirementRefs": [
        "financial-evidence"
      ]
    },
    {
      "id": "o2-critical-review",
      "description": "A critical supplier with clear sanctions screening receives review.",
      "when": {
        "op": "all",
        "conditions": [
          {
            "op": "fact",
            "path": "/vendor/sanctionsStatus",
            "operator": "equals",
            "value": "CLEAR"
          },
          {
            "op": "fact",
            "path": "/vendor/criticalSupplier",
            "operator": "equals",
            "value": "yes"
          }
        ]
      },
      "outcome": "review",
      "onUnknown": "ignore",
      "evidenceRequirementRefs": [
        "financial-evidence"
      ]
    },
    {
      "id": "d3-critical-risk",
      "description": "Reject a clear-screened request with risk score at least 90.",
      "when": {
        "op": "all",
        "conditions": [
          {
            "op": "fact",
            "path": "/vendor/sanctionsStatus",
            "operator": "equals",
            "value": "CLEAR"
          },
          {
            "op": "fact",
            "path": "/vendor/riskScore",
            "operator": "greater-than-or-equal",
            "value": "90"
          }
        ]
      },
      "outcome": "reject",
      "onUnknown": "ignore"
    },
    {
      "id": "d4-high-country-elevated-risk",
      "description": "Reject a clear-screened high-country-risk request with risk score at least 70.",
      "when": {
        "op": "all",
        "conditions": [
          {
            "op": "fact",
            "path": "/vendor/sanctionsStatus",
            "operator": "equals",
            "value": "CLEAR"
          },
          {
            "op": "fact",
            "path": "/vendor/countryRisk",
            "operator": "equals",
            "value": "HIGH"
          },
          {
            "op": "fact",
            "path": "/vendor/riskScore",
            "operator": "greater-than-or-equal",
            "value": "70"
          }
        ]
      },
      "outcome": "reject",
      "onUnknown": "ignore"
    },
    {
      "id": "d5-prior-enforcement",
      "description": "Reject a clear-screened vendor with a recorded prior enforcement action.",
      "when": {
        "op": "all",
        "conditions": [
          {
            "op": "fact",
            "path": "/vendor/sanctionsStatus",
            "operator": "equals",
            "value": "CLEAR"
          },
          {
            "op": "fact",
            "path": "/vendor/priorEnforcement",
            "operator": "equals",
            "value": "yes"
          }
        ]
      },
      "outcome": "reject",
      "onUnknown": "ignore"
    },
    {
      "id": "d6a-low-basic-approval",
      "description": "Approve a low-country-risk request below risk 40 with spend at most 500000.00.",
      "when": {
        "op": "all",
        "conditions": [
          {
            "op": "fact",
            "path": "/vendor/sanctionsStatus",
            "operator": "equals",
            "value": "CLEAR"
          },
          {
            "op": "fact",
            "path": "/vendor/countryRisk",
            "operator": "equals",
            "value": "LOW"
          },
          {
            "op": "fact",
            "path": "/vendor/riskScore",
            "operator": "less-than",
            "value": "40"
          },
          {
            "op": "fact",
            "path": "/vendor/requestedSpend",
            "operator": "less-than-or-equal",
            "value": "500000.00"
          }
        ]
      },
      "outcome": "approve",
      "onUnknown": "ignore"
    },
    {
      "id": "d6b-insured-approval",
      "description": "Approve an insured low-country-risk request below risk 40 with spend above 500000.00 and at most 2000000.00.",
      "when": {
        "op": "all",
        "conditions": [
          {
            "op": "fact",
            "path": "/vendor/sanctionsStatus",
            "operator": "equals",
            "value": "CLEAR"
          },
          {
            "op": "fact",
            "path": "/vendor/countryRisk",
            "operator": "equals",
            "value": "LOW"
          },
          {
            "op": "fact",
            "path": "/vendor/riskScore",
            "operator": "less-than",
            "value": "40"
          },
          {
            "op": "fact",
            "path": "/vendor/requestedSpend",
            "operator": "greater-than",
            "value": "500000.00"
          },
          {
            "op": "fact",
            "path": "/vendor/requestedSpend",
            "operator": "less-than-or-equal",
            "value": "2000000.00"
          },
          {
            "op": "evidence-present",
            "evidenceRequirement": "insurance-certificate"
          }
        ]
      },
      "outcome": "approve",
      "onUnknown": "ignore"
    },
    {
      "id": "d6b-uninsured-enhanced-review",
      "description": "Send an uninsured low-country-risk request below risk 40 with spend above 500000.00 and at most 2000000.00 to enhanced review.",
      "when": {
        "op": "all",
        "conditions": [
          {
            "op": "fact",
            "path": "/vendor/sanctionsStatus",
            "operator": "equals",
            "value": "CLEAR"
          },
          {
            "op": "fact",
            "path": "/vendor/countryRisk",
            "operator": "equals",
            "value": "LOW"
          },
          {
            "op": "fact",
            "path": "/vendor/riskScore",
            "operator": "less-than",
            "value": "40"
          },
          {
            "op": "fact",
            "path": "/vendor/requestedSpend",
            "operator": "greater-than",
            "value": "500000.00"
          },
          {
            "op": "fact",
            "path": "/vendor/requestedSpend",
            "operator": "less-than-or-equal",
            "value": "2000000.00"
          },
          {
            "op": "not",
            "condition": {
              "op": "evidence-present",
              "evidenceRequirement": "insurance-certificate"
            }
          }
        ]
      },
      "outcome": "enhanced-review",
      "onUnknown": "ignore"
    },
    {
      "id": "d6c-low-moderate-risk-approval",
      "description": "Approve a low-country-risk request from risk 40 through 69 with spend at most 100000.00, subject to the new-vendor suspension.",
      "when": {
        "op": "all",
        "conditions": [
          {
            "op": "fact",
            "path": "/vendor/sanctionsStatus",
            "operator": "equals",
            "value": "CLEAR"
          },
          {
            "op": "fact",
            "path": "/vendor/countryRisk",
            "operator": "equals",
            "value": "LOW"
          },
          {
            "op": "fact",
            "path": "/vendor/riskScore",
            "operator": "greater-than-or-equal",
            "value": "40"
          },
          {
            "op": "fact",
            "path": "/vendor/riskScore",
            "operator": "less-than",
            "value": "70"
          },
          {
            "op": "fact",
            "path": "/vendor/requestedSpend",
            "operator": "less-than-or-equal",
            "value": "100000.00"
          }
        ]
      },
      "outcome": "approve",
      "onUnknown": "ignore"
    },
    {
      "id": "d7-medium-basic-approval",
      "description": "Approve a medium-country-risk request below risk 40 with spend at most 100000.00.",
      "when": {
        "op": "all",
        "conditions": [
          {
            "op": "fact",
            "path": "/vendor/sanctionsStatus",
            "operator": "equals",
            "value": "CLEAR"
          },
          {
            "op": "fact",
            "path": "/vendor/countryRisk",
            "operator": "equals",
            "value": "MEDIUM"
          },
          {
            "op": "fact",
            "path": "/vendor/riskScore",
            "operator": "less-than",
            "value": "40"
          },
          {
            "op": "fact",
            "path": "/vendor/requestedSpend",
            "operator": "less-than-or-equal",
            "value": "100000.00"
          }
        ]
      },
      "outcome": "approve",
      "onUnknown": "ignore"
    },
    {
      "id": "d8-residual-review",
      "description": "Review every clear-screened request not determined by D3 through D7, including a D6c request suspended for a new vendor.",
      "when": {
        "op": "all",
        "conditions": [
          {
            "op": "fact",
            "path": "/vendor/sanctionsStatus",
            "operator": "equals",
            "value": "CLEAR"
          },
          {
            "op": "not",
            "condition": {
              "op": "any",
              "conditions": [
                {
                  "op": "fact",
                  "path": "/vendor/riskScore",
                  "operator": "greater-than-or-equal",
                  "value": "90"
                },
                {
                  "op": "all",
                  "conditions": [
                    {
                      "op": "fact",
                      "path": "/vendor/countryRisk",
                      "operator": "equals",
                      "value": "HIGH"
                    },
                    {
                      "op": "fact",
                      "path": "/vendor/riskScore",
                      "operator": "greater-than-or-equal",
                      "value": "70"
                    }
                  ]
                },
                {
                  "op": "all",
                  "conditions": [
                    {
                      "op": "fact",
                      "path": "/vendor/countryRisk",
                      "operator": "equals",
                      "value": "LOW"
                    },
                    {
                      "op": "fact",
                      "path": "/vendor/riskScore",
                      "operator": "less-than",
                      "value": "40"
                    },
                    {
                      "op": "fact",
                      "path": "/vendor/requestedSpend",
                      "operator": "less-than-or-equal",
                      "value": "500000.00"
                    }
                  ]
                },
                {
                  "op": "all",
                  "conditions": [
                    {
                      "op": "fact",
                      "path": "/vendor/countryRisk",
                      "operator": "equals",
                      "value": "LOW"
                    },
                    {
                      "op": "fact",
                      "path": "/vendor/riskScore",
                      "operator": "less-than",
                      "value": "40"
                    },
                    {
                      "op": "fact",
                      "path": "/vendor/requestedSpend",
                      "operator": "greater-than",
                      "value": "500000.00"
                    },
                    {
                      "op": "fact",
                      "path": "/vendor/requestedSpend",
                      "operator": "less-than-or-equal",
                      "value": "2000000.00"
                    },
                    {
                      "op": "evidence-present",
                      "evidenceRequirement": "insurance-certificate"
                    }
                  ]
                },
                {
                  "op": "all",
                  "conditions": [
                    {
                      "op": "fact",
                      "path": "/vendor/countryRisk",
                      "operator": "equals",
                      "value": "LOW"
                    },
                    {
                      "op": "fact",
                      "path": "/vendor/riskScore",
                      "operator": "less-than",
                      "value": "40"
                    },
                    {
                      "op": "fact",
                      "path": "/vendor/requestedSpend",
                      "operator": "greater-than",
                      "value": "500000.00"
                    },
                    {
                      "op": "fact",
                      "path": "/vendor/requestedSpend",
                      "operator": "less-than-or-equal",
                      "value": "2000000.00"
                    },
                    {
                      "op": "not",
                      "condition": {
                        "op": "evidence-present",
                        "evidenceRequirement": "insurance-certificate"
                      }
                    }
                  ]
                },
                {
                  "op": "all",
                  "conditions": [
                    {
                      "op": "fact",
                      "path": "/vendor/countryRisk",
                      "operator": "equals",
                      "value": "LOW"
                    },
                    {
                      "op": "fact",
                      "path": "/vendor/riskScore",
                      "operator": "greater-than-or-equal",
                      "value": "40"
                    },
                    {
                      "op": "fact",
                      "path": "/vendor/riskScore",
                      "operator": "less-than",
                      "value": "70"
                    },
                    {
                      "op": "fact",
                      "path": "/vendor/requestedSpend",
                      "operator": "less-than-or-equal",
                      "value": "100000.00"
                    },
                    {
                      "op": "not",
                      "condition": {
                        "op": "fact",
                        "path": "/vendor/newVendor",
                        "operator": "equals",
                        "value": "yes"
                      }
                    }
                  ]
                },
                {
                  "op": "all",
                  "conditions": [
                    {
                      "op": "fact",
                      "path": "/vendor/countryRisk",
                      "operator": "equals",
                      "value": "MEDIUM"
                    },
                    {
                      "op": "fact",
                      "path": "/vendor/riskScore",
                      "operator": "less-than",
                      "value": "40"
                    },
                    {
                      "op": "fact",
                      "path": "/vendor/requestedSpend",
                      "operator": "less-than-or-equal",
                      "value": "100000.00"
                    }
                  ]
                }
              ]
            }
          }
        ]
      },
      "outcome": "review",
      "onUnknown": "escalate"
    }
  ],
  "exceptions": [
    {
      "id": "o3-large-high-country-exposure",
      "description": "Escalate a clear-screened high-country-risk request with spend above 2000000.00 for human determination.",
      "when": {
        "op": "all",
        "conditions": [
          {
            "op": "fact",
            "path": "/vendor/sanctionsStatus",
            "operator": "equals",
            "value": "CLEAR"
          },
          {
            "op": "fact",
            "path": "/vendor/countryRisk",
            "operator": "equals",
            "value": "HIGH"
          },
          {
            "op": "fact",
            "path": "/vendor/requestedSpend",
            "operator": "greater-than",
            "value": "2000000.00"
          }
        ]
      },
      "effect": "escalate",
      "onUnknown": "escalate"
    },
    {
      "id": "o1-suspend-d6c",
      "description": "Suppress D6c for a new vendor.",
      "when": {
        "op": "fact",
        "path": "/vendor/newVendor",
        "operator": "equals",
        "value": "yes"
      },
      "effect": "suppress-rule",
      "targetRule": "d6c-low-moderate-risk-approval",
      "onUnknown": "ignore"
    },
    {
      "id": "o2-suppress-d3",
